/**
 * @summary List raw supplier rooms
 */
export const getListSupplierRoomsUrl = (params?: ListSupplierRoomsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/supplier-rooms?${stringifiedParams}`
    : `/api/v1/supplier-rooms`;
};

export const listSupplierRooms = async (
  params?: ListSupplierRoomsParams,
  options?: RequestInit,
): Promise<SupplierRoomList> => {
  return customFetch<SupplierRoomList>(getListSupplierRoomsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListSupplierRoomsQueryKey = (
  params?: ListSupplierRoomsParams,
) => {
  return [`/api/v1/supplier-rooms`, ...(params ? [params] : [])] as const;
};

export const getListSupplierRoomsQueryOptions = <
  TData = Awaited<ReturnType<typeof listSupplierRooms>>,
  TError = ErrorType<unknown>,
>(
  params?: ListSupplierRoomsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listSupplierRooms>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getListSupplierRoomsQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof listSupplierRooms>>
  > = ({ signal }) => listSupplierRooms(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listSupplierRooms>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListSupplierRoomsQueryResult = NonNullable<
  Awaited<ReturnType<typeof listSupplierRooms>>
>;
export type ListSupplierRoomsQueryError = ErrorType<unknown>;

/**
 * @summary List raw supplier rooms
 */

export function useListSupplierRooms<
  TData = Awaited<ReturnType<typeof listSupplierRooms>>,
  TError = ErrorType<unknown>,
>(
  params?: ListSupplierRoomsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listSupplierRooms>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getListSupplierRoomsQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
